private Element paneAt(double mouseX, double mouseY) {
    Document document = this.getLinkedDocument();
    if (document == null) {
        return null;
    }
    Element dual = document.getElementById("findme-house-dual");
    if (dual != null) {
        Position position = Position.of((Element)dual);
        Size size = Size.of((Element)dual);
        if (mouseX >= position.x && mouseX <= position.x + size.width() && mouseY >= position.y && mouseY <= position.y + size.height()) {
            String side = mouseX < position.x + size.width() / 2.0 ? SIDE_HOME : SIDE_OUTSIDE;
            return document.getElementById(FindMeAuiHouseScreen.paneId(side));
        }
    }
    for (String side : List.of(SIDE_HOME, SIDE_OUTSIDE)) {
        Element pane = document.getElementById(FindMeAuiHouseScreen.paneId(side));
        if (pane == null) continue;
        Position position = Position.of((Element)pane);
        Size size = Size.of((Element)pane);
        if (!(mouseX >= position.x) || !(mouseX <= position.x + size.width()) || !(mouseY >= position.y) || !(mouseY <= position.y + size.height())) continue;
        return pane;
    }
    return null;
}

private void updateDragGhostPosition() {
    if (this.dragGhostElement == null || this.dragSourceElement == null) {
        return;
    }
    double width = Math.max((double)this.scaled(92), Size.of((Element)this.dragSourceElement).width());
    double height = Math.max((double)this.scaled(34), Size.of((Element)this.dragSourceElement).height());
    long left = Math.round(this.dragMouseX - width / 2.0);
    long top = Math.round(this.dragMouseY - height / 2.0 - (double)this.scaled(3));
    this.dragGhostElement.setAttribute("style", "left:" + left + "px;top:" + top + "px;width:" + Math.round(width) + "px;height:" + Math.round(height) + "px");
}

private void finishDrag(MouseEvent mouse, Element target) {
    Element fallback;
    if (this.dragUuid == null || mouse.button != 0) {
        return;
    }
    if (!this.dragActive) {
        this.clearDrag();
        return;
    }
    this.dragMouseX = mouse.clientX;
    this.dragMouseY = mouse.clientY;
    UUID moved = this.dragUuid;
    String source = this.dragFromSide;
    this.updateDragTarget();
    if (this.dragTargetElement == null && target != null && (fallback = target.closest("[data-house-side]")) != null && !source.equals(fallback.getAttribute("data-house-side"))) {
        this.dragTargetElement = fallback;
    }
    String destination = this.dragTargetElement == null ? null : this.dragTargetElement.getAttribute("data-house-side");
    this.suppressClickTicks = 2;
    this.clearDrag();
    if (destination != null && !destination.equals(source)) {
        this.move(moved, source);
    }
    mouse.preventDefault();
}

