private List<HousePagePacket.Resident> filtered(List<HousePagePacket.Resident> source, boolean newestFirst) {
    List<HousePagePacket.Resident> result;
    if (this.search.isBlank()) {
        result = new ArrayList<HousePagePacket.Resident>(source);
    } else {
        String needle = this.search.toLowerCase(Locale.ROOT);
        result = source.stream().filter(resident -> resident.name().toLowerCase(Locale.ROOT).contains(needle) || resident.entityType().toLowerCase(Locale.ROOT).contains(needle)).collect(Collectors.toCollection(ArrayList::new));
    }
    if (newestFirst) {
        Collections.reverse(result);
        result.sort((left, right) -> Boolean.compare(left.otherHouse(), right.otherHouse()));
    }
    return List.copyOf(result);
}

private int normalizedFirstVisible(String side, int size) {
    int maximum = Math.max(0, size - 4);
    int requested = SIDE_HOME.equals(side) ? this.homeFirstVisible : this.outsideFirstVisible;
    int first = Math.max(0, Math.min(maximum, requested));
    if (SIDE_HOME.equals(side)) {
        this.homeFirstVisible = first;
    } else {
        this.outsideFirstVisible = first;
    }
    return first;
}

private int normalizePartnerFirst(int size) {
    int maximum = FindMeAuiHouseScreen.maximumPartnerFirst(size);
    this.partnerFirstVisible = Math.max(0, Math.min(maximum, this.partnerFirstVisible / 4 * 4));
    return this.partnerFirstVisible;
}

private static int maximumPartnerFirst(int size) {
    int overflow = Math.max(0, size - 8);
    return (overflow + 3) / 4 * 4;
}

private HousePagePacket.Resident resident(UUID uuid) {
    if (uuid == null) {
        return null;
    }
    for (HousePagePacket.Resident resident : this.page.residents()) {
        if (!uuid.equals(resident.uuid())) continue;
        return resident;
    }
    for (HousePagePacket.Resident resident : this.page.available()) {
        if (!uuid.equals(resident.uuid())) continue;
        return resident;
    }
    return null;
}

